#include <catch2/catch_all.hpp>

#include "slic3r/GUI/JusPrin/Support/SentryEnvelope.hpp"

#include <nlohmann/json.hpp>

#include <sstream>
#include <string>
#include <vector>

using namespace Slic3r::GUI::JusPrin;

namespace {

const ErrorReport kReport{"JusPrin 2.0.1 (OrcaSlicer 2.5.0)", "macOS 26.3", "exporting G-code from Home",
                          "std::filesystem::filesystem_error: filesystem error: in copy_file: Permission denied", ""};

// The envelope's three lines: its header, the item's header, the event.
std::vector<nlohmann::json> lines_of(const std::string& envelope)
{
    std::vector<nlohmann::json> lines;
    std::istringstream          in(envelope);
    for (std::string line; std::getline(in, line);)
        lines.push_back(nlohmann::json::parse(line));
    return lines;
}

// What the app sends for one provider refusal: its own request and the
// provider's request id differ every time.
ErrorReport refusal(const std::string& turn, const std::string& request_id, int status = 400)
{
    ErrorReport report = kReport;
    report.doing       = "answering in the chat";
    report.error = "Anthropic answered HTTP " + std::to_string(status) + " (request " + turn + " #1, its request id " + request_id +
                   "): {\"type\":\"error\",\"error\":{\"type\":\"invalid_request_error\",\"message\":\"thinking blocks cannot be "
                   "modified.\"},\"request_id\":\"" +
                   request_id + "\"}";
    return report;
}

} // namespace

TEST_CASE("A DSN names the envelope address and the key", "[SentryEnvelope]")
{
    const std::optional<SentryDsn> plain = parse_sentry_dsn("https://abc123@errors.example.com/16");
    REQUIRE(plain);
    CHECK(plain->envelope_url == "https://errors.example.com/api/16/envelope/");
    CHECK(plain->public_key == "abc123");

    const std::optional<SentryDsn> stand_in = parse_sentry_dsn("REDACTED");
    REQUIRE(stand_in);
    CHECK(stand_in->envelope_url == "http://127.0.0.1:8123/prefix/api/16/envelope/");
    CHECK(stand_in->public_key == "key");

    CHECK(sentry_auth_header(*plain, "jusprin.app/2.0.1") == "Sentry sentry_version=7, sentry_client=jusprin.app/2.0.1, sentry_key=abc123");
}

TEST_CASE("An empty or misshapen DSN names nowhere to send", "[SentryEnvelope]")
{
    const std::string dsn = GENERATE("", "https://errors.example.com/16", "ftp://k@errors.example.com/16", "https://k@errors.example.com/",
                                     "https://k@errors.example.com/project");
    CAPTURE(dsn);
    CHECK_FALSE(parse_sentry_dsn(dsn));
}

TEST_CASE("The envelope carries the report as one event filed by release and tags", "[SentryEnvelope]")
{
    const std::vector<nlohmann::json> lines = lines_of(sentry_envelope(kReport, "0123456789abcdef0123456789abcdef", 1763400000.5, "2.0.1"));
    REQUIRE(lines.size() == 3);
    CHECK(lines[0]["event_id"] == "0123456789abcdef0123456789abcdef");
    CHECK(lines[1]["type"] == "event");
    CHECK(lines[1]["length"] == lines[2].dump().size());

    const nlohmann::json& event = lines[2];
    CHECK(event["event_id"] == "0123456789abcdef0123456789abcdef");
    CHECK(event["level"] == "error");
    CHECK(event["release"] == kReport.app);
    CHECK(event["message"]["formatted"] == kReport.error);
    CHECK(event["tags"] == nlohmann::json{{"doing", kReport.doing}, {"os", kReport.os}});
    CHECK(event["extra"] == nlohmann::json{{"doing", kReport.doing}, {"where", ""}});
}

TEST_CASE("The event never asks Sentry for the sender's network address", "[SentryEnvelope]")
{
    ErrorReport with_stack = kReport;
    with_stack.where       = "TypeError: x is undefined\n    at render (index.js:1:200)";
    const ErrorReport report = GENERATE_COPY(kReport, with_stack);
    const nlohmann::json event = lines_of(sentry_envelope(report, "0123456789abcdef0123456789abcdef", 1.0, "2.0.1"))[2];
    CHECK(event["platform"] == "native");
    CHECK_FALSE(event.contains("user"));
    CHECK_FALSE(event.contains("request"));
    CHECK(event["sdk"]["settings"]["infer_ip"] == "never");
    CHECK(event["extra"]["where"] == report.where);
}

TEST_CASE("A tag keeps at most 200 bytes, cut on a character boundary", "[SentryEnvelope]")
{
    ErrorReport report = kReport;
    report.doing       = std::string(199, 'a') + "\xC3\xA9" + "tail"; // "é" straddles byte 200
    const nlohmann::json event = lines_of(sentry_envelope(report, "0123456789abcdef0123456789abcdef", 1.0, "2.0.1"))[2];
    CHECK(event["tags"]["doing"] == std::string(199, 'a'));
    CHECK(event["extra"]["doing"] == report.doing);
}

TEST_CASE("Two reports of one failure are one Sentry issue and keep their ids", "[SentryEnvelope]")
{
    const ErrorReport first  = refusal("p1-c1-m1-attempt-1", "req_011A");
    const ErrorReport second = refusal("p1-c1-m7-attempt-2", "req_022B");
    const ErrorReport other  = refusal("p1-c1-m9-attempt-1", "req_033C", 500);
    CHECK(sentry_fingerprint(first) == sentry_fingerprint(second));
    CHECK(sentry_fingerprint(first) != sentry_fingerprint(other));
    CHECK(sentry_fingerprint(first)[0] == "answering in the chat");

    const nlohmann::json event = lines_of(sentry_envelope(second, "0123456789abcdef0123456789abcdef", 1.0, "2.0.1"))[2];
    CHECK(event["fingerprint"] == nlohmann::json(sentry_fingerprint(second)));
    const std::string message = event["message"]["formatted"];
    CHECK(message.find("p1-c1-m7-attempt-2") != std::string::npos);
    CHECK(message.find("req_022B") != message.rfind("req_022B"));
}

