// usage: probe <db> <handler> <dsn> <retry 0|1> <mode>
// modes: capture-unknown | capture-revoked | give-capture-revoke | crash-revoked | start-give | start-only | crash-given
#include <sentry.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <unistd.h>

static void boom(void) { volatile int *p = 0; *p = 1; }

int main(int argc, char **argv)
{
    const char *db = argv[1], *handler = argv[2], *dsn = argv[3], *mode = argv[5];
    sentry_options_t *o = sentry_options_new();
    sentry_options_set_dsn(o, dsn);
    sentry_options_set_database_path(o, db);
    sentry_options_set_handler_path(o, handler);
    sentry_options_set_release(o, "JusPrin 2.0.1 (OrcaSlicer 2.5.0)");
    sentry_options_set_require_user_consent(o, 1);
    sentry_options_set_auto_session_tracking(o, 0);
    sentry_options_set_debug(o, 1);
    if (atoi(argv[4])) sentry_options_set_http_retry(o, 1);
    sentry_init(o);
    printf("consent at start: %d, crashed last run: %d\n", sentry_user_consent_get(), sentry_get_crashed_last_run());
    sentry_add_breadcrumb(sentry_value_new_breadcrumb("default", "opened the Home page"));
    if (!strcmp(mode, "capture-revoked")) sentry_user_consent_revoke();
    if (!strcmp(mode, "give-capture-revoke") || !strcmp(mode, "crash-given") || !strcmp(mode, "start-give")) sentry_user_consent_give();
    if (!strncmp(mode, "capture", 7) || !strcmp(mode, "give-capture-revoke")) {
        sentry_value_t ev = sentry_value_new_message_event(SENTRY_LEVEL_ERROR, "jusprin.app", "probe failure (request p1 #1, its request id req_X)");
        sentry_event_value_add_stacktrace(ev, NULL, 0);
        sentry_capture_event(ev);
    }
    if (!strcmp(mode, "give-capture-revoke")) sentry_user_consent_revoke();
    if (!strcmp(mode, "crash-revoked")) { sentry_user_consent_revoke(); boom(); }
    if (!strcmp(mode, "crash-given")) boom();
    if (!strncmp(mode, "start", 5)) sleep(8);
    sentry_close();
    printf("consent at end: %d\n", sentry_user_consent_get());
    return 0;
}

