#include "SentryEvent.hpp"

#include "slic3r/GUI/JusPrin/Support/ErrorReport.hpp"

#include <sentry.h>

#include <algorithm>
#include <cstddef>
#include <optional>
#include <regex>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin {

namespace {

// Where a page event keeps its own debug_meta while the SDK fills the event:
// the SDK replaces debug_meta with the app's modules (sentry_scope.c), and
// the page's names its source maps.
constexpr const char* kPageDebugMeta = "jusprin_page_debug_meta";

// Sentry keeps at most 200 characters of a tag's value; cutting at as many
// bytes, on a character boundary, keeps within it.
std::string tag_value(std::string text)
{
    constexpr std::size_t limit = 200;
    if (text.size() > limit) {
        std::size_t end = limit;
        while (end > 0 && (static_cast<unsigned char>(text[end]) & 0xC0) == 0x80)
            --end;
        text.resize(end);
    }
    return text;
}

// The object under `key`, made when there is none.
sentry_value_t object_at(sentry_value_t parent, const char* key)
{
    sentry_value_t child = sentry_value_get_by_key(parent, key);
    if (sentry_value_get_type(child) != SENTRY_VALUE_TYPE_OBJECT) {
        sentry_value_set_by_key(parent, key, sentry_value_new_object());
        child = sentry_value_get_by_key(parent, key);
    }
    return child;
}

std::string to_json(sentry_value_t value)
{
    char* const text = sentry_value_to_json(value);
    std::string json = text != nullptr ? text : "null";
    sentry_free(text);
    return json;
}

void replace_all(std::string& text, const std::string& from, const std::string& to)
{
    if (from.empty())
        return;
    for (std::size_t at = text.find(from); at != std::string::npos; at = text.find(from, at + to.size()))
        text.replace(at, from.size(), to);
}

} // namespace

std::optional<SentryDsn> parse_sentry_dsn(const std::string& dsn)
{
    // <scheme>://<key>[:<secret>]@<host>[:<port>][/<path>]/<project>
    static const std::regex shape(R"(^(https?)://([^:@/]+)(?::[^@/]*)?@([^/]+)(/(?:[^/]+/)*)([0-9]+)/?$)");
    std::smatch part;
    if (!std::regex_match(dsn, part, shape))
        return std::nullopt;
    return SentryDsn{part[1].str() + "://" + part[3].str() + part[4].str() + "api/" + part[5].str() + "/envelope/", part[2].str()};
}

std::string sentry_auth_header(const SentryDsn& dsn, const std::string& client)
{
    return "Sentry sentry_version=7, sentry_client=" + client + ", sentry_key=" + dsn.public_key;
}

std::vector<std::string> sentry_fingerprint(const ErrorReport& report)
{
    static const std::regex request_ids(R"( \(request [^()]*\)|"request_id"\s*:\s*"[^"]*")");
    return {report.doing, std::regex_replace(report.error, request_ids, "")};
}

sentry_value_t sentry_event(const ErrorReport& report)
{
    sentry_value_t event;
    if (report.page_event.empty()) {
        event = sentry_value_new_message_event(SENTRY_LEVEL_ERROR, "jusprin.app", report.error.c_str());
    } else {
        event = sentry_value_from_json(report.page_event.data(), report.page_event.size());
        sentry_value_t debug_meta = sentry_value_get_by_key(event, "debug_meta");
        if (!sentry_value_is_null(debug_meta)) {
            sentry_value_incref(debug_meta);
            sentry_value_set_by_key(event, kPageDebugMeta, debug_meta);
        }
        sentry_value_set_by_key(event, "level", sentry_value_new_string("error"));
    }
    sentry_value_set_by_key(event, "release", sentry_value_new_string(report.app.c_str()));

    sentry_value_t tags = object_at(event, "tags");
    sentry_value_set_by_key(tags, "doing", sentry_value_new_string(tag_value(report.doing).c_str()));
    sentry_value_set_by_key(tags, "os", sentry_value_new_string(tag_value(report.os).c_str()));

    sentry_value_t extra = object_at(event, "extra");
    sentry_value_set_by_key(extra, "doing", sentry_value_new_string(report.doing.c_str()));
    sentry_value_set_by_key(extra, "error", sentry_value_new_string(report.error.c_str()));
    sentry_value_set_by_key(extra, "where", sentry_value_new_string(report.where.c_str()));

    sentry_value_t fingerprint = sentry_value_new_list();
    for (const std::string& part : sentry_fingerprint(report))
        sentry_value_append(fingerprint, sentry_value_new_string(part.c_str()));
    sentry_value_set_by_key(event, "fingerprint", fingerprint);
    return event;
}

void scrub_sentry_event(sentry_value_t event, const std::string& home)
{
    sentry_value_remove_by_key(event, "user");
    sentry_value_t page_debug_meta = sentry_value_get_by_key(event, kPageDebugMeta);
    if (!sentry_value_is_null(page_debug_meta)) {
        sentry_value_incref(page_debug_meta);
        sentry_value_set_by_key(event, "debug_meta", page_debug_meta);
        sentry_value_remove_by_key(event, kPageDebugMeta);
    }
    sentry_value_set_by_key(object_at(object_at(event, "sdk"), "settings"), "infer_ip", sentry_value_new_string("never"));

    if (home.size() <= 1)
        return;
    // Every string, wherever the SDK put it: module paths, stack frames, a
    // page's address, breadcrumbs. Matched as the event's JSON writes it, and
    // with forward slashes, as a page's file:// address writes a Windows one.
    std::string json = to_json(event);
    std::string written = to_json(sentry_value_new_string(home.c_str()));
    written = written.substr(1, written.size() - 2);
    std::string forward = home;
    std::replace(forward.begin(), forward.end(), '\\', '/');
    replace_all(json, written, "~");
    replace_all(json, forward, "~");
    sentry_value_t scrubbed = sentry_value_from_json(json.data(), json.size());

    // The SDK owns `event`; its contents become the scrubbed ones.
    std::vector<std::string> keys;
    sentry_value_foreach_key_value(
        event,
        [](const char* key, sentry_value_t, void* data) {
            static_cast<std::vector<std::string>*>(data)->emplace_back(key);
            return 0;
        },
        &keys);
    for (const std::string& key : keys)
        sentry_value_remove_by_key(event, key.c_str());
    sentry_value_foreach_key_value(
        scrubbed,
        [](const char* key, sentry_value_t value, void* data) {
            sentry_value_incref(value);
            sentry_value_set_by_key(*static_cast<sentry_value_t*>(data), key, value);
            return 0;
        },
        &event);
    sentry_value_decref(scrubbed);
}

} // namespace Slic3r::GUI::JusPrin

