// The top of a page's own code (AGENTS.md, Error handling): Sentry's browser
// SDK catches what nothing else did -- an uncaught error, a rejected promise --
// and builds its event with the stack, the recent steps and the page's
// context. The event is not sent from here: it goes to the app as a
// report_error message, and the app asks the person, or not when automatic
// reports are on, and sends it with its own Sentry SDK (Support/SentryClient).
// The page holds no Sentry project and never reaches the network for this.
import {
  breadcrumbsIntegration,
  createTransport,
  init,
  rewriteFramesIntegration,
  type Breadcrumb,
  type ErrorEvent,
  type EventHint,
  type Integration,
} from '@sentry/browser';

// What a page sends the app: the two lines the report dialog shows, and the
// event Sentry receives.
export interface PageErrorReport {
  error: string;
  where: string;
  event: ErrorEvent;
}

// The SDK runs only with a DSN. This one names no host that exists, and the
// transport below never sends: every event leaves through beforeSend.
const NOWHERE = 'https://page@jusprin.invalid/0';

// Integrations left out: the console's lines can hold what the person wrote,
// and sessions are not reports.
const LEFT_OUT = new Set(['Console', 'BrowserSession', 'Breadcrumbs']);

let started = false;

// A click or key step names the element by its tag and classes; the SDK also
// copies its aria-label, title or alt, which can be a project's or a file's
// name, so those go.
function withoutPersonalText(crumb: Breadcrumb): Breadcrumb {
  if (crumb.category?.startsWith('ui.') && typeof crumb.message === 'string') {
    crumb.message = crumb.message.replace(/\[[^\]]*\]/g, '');
  }
  if ((crumb.category === 'fetch' || crumb.category === 'xhr') && typeof crumb.data?.url === 'string') {
    crumb.data.url = crumb.data.url.split('?')[0];
  }
  return crumb;
}

export function reportOf(event: ErrorEvent, hint: EventHint): PageErrorReport {
  const original = hint.originalException;
  if (original instanceof Error) {
    return { error: `${original.name}: ${original.message}`, where: original.stack ?? '', event };
  }
  const exception = event.exception?.values?.at(-1);
  const error = exception ? `${exception.type ?? 'Error'}: ${exception.value ?? ''}` : String(original);
  return { error, where: '', event };
}

// Starts catching, once per page; `deliver` hands each report to the app.
export function startErrorReports(deliver: (report: PageErrorReport) => void): void {
  if (started) return;
  started = true;
  init({
    dsn: NOWHERE,
    transport: (options) => createTransport(options, () => Promise.resolve({})),
    sendClientReports: false,
    integrations: (defaults: Integration[]) => [
      ...defaults.filter((integration) => !LEFT_OUT.has(integration.name)),
      breadcrumbsIntegration({ dom: true, fetch: true, history: true, xhr: true, sentry: false }),
      // The page is one file, wherever the app is installed: its frames are
      // named app:///index.html, which names no folder of the person's and
      // is where the page's source maps are found.
      rewriteFramesIntegration({ prefix: 'app:///' }),
    ],
    beforeBreadcrumb: withoutPersonalText,
    beforeSend(event, hint) {
      deliver(reportOf(event, hint));
      return null;
    },
  });
}

