#pragma once

// Where an exception was thrown, so a report's stack is the throw's and not
// the handler's that reported it (AGENTS.md, Error handling: a failure
// travels up unchanged to one handler). Boost 1.84 in this build cannot do
// this (boost::stacktrace::from_current_exception came in 1.85), nor can
// Sentry's SDK, so the app records each C++ throw itself.
//
// macOS and Linux: every throw from the app's own code and its static
// libraries (wx, boost, OCCT...) passes the app's __cxa_throw. A throw inside
// the system's C++ library (libc++.dylib on macOS) is not seen. Linux's
// libstdc++ calls the app's, so it is.
// Windows: a vectored exception handler sees every C++ throw in the process;
// the handler that reports takes the latest one made on its own thread.

#include <vector>

namespace Slic3r::GUI::JusPrin {

// Starts recording on Windows; does nothing elsewhere, where recording needs
// no start. Once, early.
void start_recording_throws();

// The stack, innermost first, where the exception being handled was thrown;
// empty outside a catch block or when its throw was not recorded.
std::vector<void*> current_exception_throw_stack();

} // namespace Slic3r::GUI::JusPrin

#include "ThrowStack.hpp"

#include <array>
#include <cstddef>
#include <exception>
#include <mutex>
#include <vector>

#ifdef _WIN32
#include <windows.h>
#else
#include <cstring>
#include <cxxabi.h>
#include <dlfcn.h>
#include <execinfo.h>
#include <typeinfo>
#endif

namespace Slic3r::GUI::JusPrin {

namespace {

constexpr int kFrames = 64;

struct Throw
{
    const void*                 object = nullptr; // the thrown object, which names the throw
    int                         depth  = 0;
    std::array<void*, kFrames>  frames{};
};

#ifndef _WIN32

// The latest throws of every thread: an exception can be thrown on one and
// reported on another (std::exception_ptr). The newest throw of an object
// is its own, since an address is only reused once its exception is gone.
constexpr std::size_t kKept = 32;
std::mutex            g_mutex;
std::array<Throw, kKept> g_throws;
std::size_t           g_next = 0;

void record(const void* object)
{
    Throw throw_here;
    throw_here.object = object;
    // Leaves out __cxa_throw's own frame: the first is the throwing function.
    std::array<void*, kFrames + 1> frames{};
    const int depth = backtrace(frames.data(), static_cast<int>(frames.size()));
    for (int i = 1; i < depth; ++i)
        throw_here.frames[static_cast<std::size_t>(i - 1)] = frames[static_cast<std::size_t>(i)];
    throw_here.depth = depth > 0 ? depth - 1 : 0;
    std::lock_guard<std::mutex> lock(g_mutex);
    g_throws[g_next++ % kKept] = throw_here;
}

#else

// Per thread: the handler runs on the throwing thread, and a report made
// inside a catch block is about that thread's latest throw.
thread_local Throw t_latest;

LONG CALLBACK on_exception(EXCEPTION_POINTERS* info)
{
    const EXCEPTION_RECORD* record = info->ExceptionRecord;
    // 0xE06D7363 is a C++ throw; a bare `throw;` passes no object.
    if (record->ExceptionCode == 0xE06D7363 && record->NumberParameters >= 3 && record->ExceptionInformation[1] != 0) {
        t_latest.object = reinterpret_cast<const void*>(record->ExceptionInformation[1]);
        t_latest.depth  = CaptureStackBackTrace(0, kFrames, t_latest.frames.data(), nullptr);
    }
    return EXCEPTION_CONTINUE_SEARCH;
}

#endif

} // namespace

#ifndef _WIN32

void start_recording_throws() {}

std::vector<void*> current_exception_throw_stack()
{
    const std::exception_ptr current = std::current_exception();
    if (!current)
        return {};
    // libc++'s and libstdc++'s exception_ptr is the thrown object's address.
    static_assert(sizeof(std::exception_ptr) == sizeof(void*));
    const void* object = nullptr;
    std::memcpy(&object, &current, sizeof object);
    std::lock_guard<std::mutex> lock(g_mutex);
    for (std::size_t back = 1; back <= kKept && back <= g_next; ++back) {
        const Throw& seen = g_throws[(g_next - back) % kKept];
        if (seen.object == object)
            return {seen.frames.begin(), seen.frames.begin() + seen.depth};
    }
    return {};
}

#else

void start_recording_throws()
{
    static const PVOID handler = AddVectoredExceptionHandler(1, on_exception);
    (void) handler;
}

std::vector<void*> current_exception_throw_stack()
{
    if (!std::current_exception() || t_latest.depth == 0)
        return {};
    return {t_latest.frames.begin(), t_latest.frames.begin() + t_latest.depth};
}

#endif

} // namespace Slic3r::GUI::JusPrin

#ifndef _WIN32

// Every C++ throw in the app's own code and static libraries comes here
// first (ThrowStack.hpp), then goes on to the C++ library's own.
extern "C" void __cxa_throw(void* object, std::type_info* type, void (*destructor)(void*))
{
    using Real       = void (*)(void*, std::type_info*, void (*)(void*));
    static Real real = reinterpret_cast<Real>(dlsym(RTLD_NEXT, "__cxa_throw"));
    Slic3r::GUI::JusPrin::record(object);
    real(object, type, destructor);
    __builtin_unreachable();
}

#endif

