    error_sizer->Add(m_error_detail, 0, wxLEFT | wxRIGHT | wxEXPAND, FromDIP(16));
    error_sizer->AddSpacer(FromDIP(16));
    error_sizer->Add(actions, 0, wxLEFT, FromDIP(16));
    m_error_panel->SetSizer(error_sizer);
    m_error_panel->Hide();
    sizer->Add(m_error_panel, 1, wxEXPAND);
    // Fonts and colours come from the theme here and on every appearance
    // change; they must be in place before a load failure below wraps the
    // detail text.
    apply_appearance(GUI_App::dark_mode());

    m_page_url = agent_page_url(mode);
    if (m_page_url.empty()) {
        show_bridge_error(_L("The packaged AI page is missing from this build."));
    } else {
        m_webview  = WebView::CreateWebView(this, m_page_url);
        if (m_webview == nullptr) {
            show_bridge_error(_L("The system web view could not be created."));
        } else {
            sizer->Add(m_webview, 1, wxEXPAND);
            m_webview->Bind(wxEVT_WEBVIEW_SCRIPT_MESSAGE_RECEIVED, &AgentWebView::on_script_message, this);
            m_webview->Bind(wxEVT_WEBVIEW_ERROR, &AgentWebView::on_load_error, this);
            m_webview->Bind(wxEVT_WEBVIEW_NAVIGATING, [this](wxWebViewEvent& event) {
                // wx reports frames inside the page too, such as Account's
                // server box (about:srcdoc). Those leave the page and its
                // handshake as they are. The main-frame flag (GetInt) is not
                // set on GTK, so the URL decides: the page itself is never an
                // about: URL.
                if (event.GetURL().StartsWith("about:")) {
                    event.Skip();
                    return;
                }
                // A file let go on the page (DroppedFileUrl.hpp). The view
                // stays on its page, and the page is asked whether the point
                // is on the message box, which attaches the file.
                if (const std::optional<wxString> file =
                        dropped_file(event.GetURL(), wxString::FromUTF8(agent_page_path().string()))) {
                    event.Veto();
                    const wxPoint point = m_webview->ToDIP(m_webview->ScreenToClient(wxGetMousePosition()));
                    m_host->offer_dropped_file(file->ToUTF8().data(), point.x, point.y);
                    return;
                }
                // Every (re)load needs a fresh handshake before other traffic.
                m_host->reset_page();
                m_handshake_timer.StartOnce(kHandshakeDeadlineMs);
                event.Skip();
            });

            m_host->set_send([this](const std::string& envelope) {
                if (m_webview == nullptr)
                    return;
                wxString script = "window.__jusprinBridge && window.__jusprinBridge.deliver(";
                script += wxString::FromUTF8(envelope);
                script += ")";
                WebView::RunScript(m_webview, script);
            });
            m_host->set_handshake_listener([this]() {
                m_handshake_timer.Stop();
                hide_bridge_error();
            });
            m_handshake_timer.StartOnce(kHandshakeDeadlineMs);
        }
    }

    Bind(wxEVT_TIMER, reported("checking the app page's handshake", [this](wxTimerEvent& event) {
        if (event.GetId() == kHandshakeTimerId)
            on_handshake_deadline(event);
        else
            event.Skip();
    }));
}

