#pragma once

#include <string>
#include <vector>

#include <wx/sharedptr.h>
#include <wx/string.h>

class wxWebViewHandler;

namespace Slic3r::GUI::JusPrin {

// Where the app's own pages load from: resources/jusprin/<page>/index.html,
// such as "home" or "agent".
//
// On macOS that is jusprin:///<page>/index.html, served from the
// resources/jusprin folder by the handler page_handlers() gives. WKWebView
// tells a file:// page nothing about an uncaught error but "Script error.",
// with no file, line or stack, so the page's Sentry gets nothing to report; a
// page on its own scheme gets all of it. On Windows and Linux the pages load
// from file:// as before: whether their web views hide errors the same way
// is untested.

// The page's address, without a query; empty when this build has no such page.
wxString page_url(const std::string& page);

// The scheme handlers a web view needs to load a page_url(), for
// WebView::CreateWebView. Empty where the pages load from file://.
std::vector<wxSharedPtr<wxWebViewHandler>> page_handlers();

} // namespace Slic3r::GUI::JusPrin

#include "PageScheme.hpp"

#include "slic3r/GUI/JusPrin/Support/PageFiles.hpp"

#include "libslic3r/Utils.hpp"

#include <filesystem>
#include <optional>

#include <wx/filename.h>
#include <wx/filesys.h>
#include <wx/uri.h>
#include <wx/webview.h>

namespace Slic3r::GUI::JusPrin {

namespace {

std::filesystem::path pages_folder() { return std::filesystem::u8path(resources_dir()) / "jusprin"; }

#ifdef __APPLE__
constexpr const char* kScheme = "jusprin";

// Serves jusprin:///<path> from the pages folder, and nothing outside it.
class PageFilesHandler : public wxWebViewHandler
{
public:
    PageFilesHandler() : wxWebViewHandler(kScheme) {}

    wxFSFile* GetFile(const wxString& uri) override
    {
        const wxString path = wxURI::Unescape(wxURI(uri).GetPath());
        const std::optional<std::filesystem::path> file = page_file(pages_folder(), std::string(path.ToUTF8()));
        if (!file)
            return nullptr;
        // The web view takes the file and frees it.
        return m_files.OpenFile(wxFileSystem::FileNameToURL(wxFileName(wxString::FromUTF8(file->u8string()))));
    }

private:
    wxFileSystem m_files;
};
#endif

} // namespace

wxString page_url(const std::string& page)
{
    const std::filesystem::path file = pages_folder() / page / "index.html";
    std::error_code             error;
    if (!std::filesystem::is_regular_file(file, error))
        return {};
#ifdef __APPLE__
    return wxString::Format("%s:///%s/index.html", kScheme, wxString::FromUTF8(page));
#else
    return wxFileSystem::FileNameToURL(wxFileName(wxString::FromUTF8(file.u8string())));
#endif
}

std::vector<wxSharedPtr<wxWebViewHandler>> page_handlers()
{
#ifdef __APPLE__
    return {wxSharedPtr<wxWebViewHandler>(new PageFilesHandler())};
#else
    return {};
#endif
}

} // namespace Slic3r::GUI::JusPrin

