1827	+std::optional<std::filesystem::path> page_file(const std::filesystem::path& root, const std::string& path)
1828	+{
1829	+    if (path.size() < 2 || path.front() != '/')
1830	+        return std::nullopt;
1831	+    std::filesystem::path file = root;
1832	+    std::string::size_type start = 1;
1833	+    while (start <= path.size()) {
1834	+        const std::string::size_type end  = std::min(path.find('/', start), path.size());
1835	+        const std::string            part = path.substr(start, end - start);
1836	+        if (part.empty() || part == "." || part == ".." || part.find('\\') != std::string::npos)
1837	+            return std::nullopt;
1838	+        file /= std::filesystem::u8path(part);
1839	+        start = end + 1;
1840	+    }
1841	+    std::error_code error;
1842	+    if (!std::filesystem::is_regular_file(file, error))
1843	+        return std::nullopt;
1844	+    return file;
1845	+}
1846	+
1847	+std::string page_file_type(const std::filesystem::path& file)
1848	+{
1849	+    std::string extension = file.extension().u8string();
1850	+    std::transform(extension.begin(), extension.end(), extension.begin(),
1851	+                   [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
1852	+    if (extension == ".html")
1853	+        return "text/html";
1854	+    if (extension == ".js" || extension == ".mjs")
1855	+        return "text/javascript";
1856	+    if (extension == ".css")
1857	+        return "text/css";
1858	+    if (extension == ".svg")
1859	+        return "image/svg+xml";
1860	+    if (extension == ".json")
1861	+        return "application/json";
1862	+    return {};
1863	+}
1864	+
1865	+} // namespace Slic3r::GUI::JusPrin
