2803	+// The top of a page's own code (AGENTS.md, Error handling): Sentry's browser
2804	+// SDK catches what nothing else did -- an uncaught error, a rejected promise --
2805	+// and builds its event with the stack, the recent steps and the page's
2806	+// context. The event is not sent from here: it goes to the app as a
2807	+// report_error message, and the app asks the person, or not when automatic
2808	+// reports are on, and sends it with its own Sentry SDK (Support/SentryClient).
2809	+// The page holds no Sentry project and never reaches the network for this.
2810	+import {
2811	+  SDK_VERSION,
2812	+  createTransport,
2813	+  init,
2814	+  rewriteFramesIntegration,
2815	+  type ErrorEvent,
2816	+  type EventHint,
2817	+} from '@sentry/browser';
2818	+
2819	+// What a page sends the app: the two lines the report dialog shows, and the
2820	+// event Sentry receives.
2821	+export interface PageErrorReport {
2822	+  error: string;
2823	+  where: string;
2824	+  event: ErrorEvent;
2825	+}
2826	+
2827	+// Which build of the page this is: the commit the release workflow built
2828	+// (JUSPRIN_PAGE_BUILD, read by vite.config.ts), "local" elsewhere. Sentry
2829	+// files the page's source map under it (Packaging/sentry_page_maps.sh), as a
2830	+// release's "dist", so builds that share a version keep their own maps.
2831	+declare const __JUSPRIN_PAGE_BUILD__: string;
2832	+
2833	+// The SDK runs only with a DSN. This one names no host that exists, and the
2834	+// transport below never sends: every event leaves through beforeSend.
2835	+const NOWHERE = 'https://page@jusprin.invalid/0';
2836	+
2837	+let started = false;
2838	+// The page's bridge client, which holds a report until the app can take it.
2839	+let deliverTo: (report: PageErrorReport) => void = () => {};
2840	+
2841	+export function reportOf(event: ErrorEvent, hint: EventHint): PageErrorReport {
2842	+  // What the SDK itself does to an event as it sends it, which here it never
2843	+  // does: names itself, and drops its own working data.
2844	+  event.sdk = { ...event.sdk, name: 'sentry.javascript.browser', version: SDK_VERSION };
2845	+  delete event.sdkProcessingMetadata;
2846	+  const original = hint.originalException;
2847	+  if (original instanceof Error) {
2848	+    return { error: `${original.name}: ${original.message}`, where: original.stack ?? '', event };
2849	+  }
2850	+  const exception = event.exception?.values?.at(-1);
2851	+  const error = exception ? `${exception.type ?? 'Error'}: ${exception.value ?? ''}` : String(original);
2852	+  return { error, where: '', event };
2853	+}
