2855	+// Starts catching, once per page, with every integration the SDK has by
2856	+// default and the one that names frames below; `deliver`, the latest bridge client's, hands each report to the app.
2857	+export function startErrorReports(deliver: (report: PageErrorReport) => void): void {
2858	+  deliverTo = deliver;
2859	+  if (started) return;
2860	+  started = true;
2861	+  // The page loads from the app's resources folder (Support/PageScheme.hpp):
2862	+  // jusprin:///home/index.html on macOS and Linux, and on Windows a file://
2863	+  // address wherever the app is installed.
2864	+  // Sentry finds the page's source map by a frame's file name
2865	+  // (Packaging/sentry_page_maps.sh), so frames name the page's folder the same
2866	+  // way on every computer: app:///home/index.html.
2867	+  const folder = new URL('.', window.location.href);
2868	+  const name = folder.pathname.split('/').filter(Boolean).pop() ?? '';
2869	+  init({
2870	+    dsn: NOWHERE,
2871	+    dist: __JUSPRIN_PAGE_BUILD__,
2872	+    integrations: [rewriteFramesIntegration({ root: folder.href, prefix: name ? `app:///${name}/` : 'app:///' })],
2873	+    transport: (options) => createTransport(options, () => Promise.resolve({})),
