2886	+// The source map Sentry needs to name the page's own code in an error's
2887	+// stack (Packaging/sentry_page_maps.sh). The page's code runs from a script
2888	+// inlined into index.html (vite-plugin-singlefile), so a stack gives lines
2889	+// and columns in index.html, not in the script Vite built. This maps those
2890	+// positions to the page's source files. The map is written beside the
2891	+// build, never into the folder the app ships.
2892	+import { mkdirSync, writeFileSync } from 'node:fs';
2893	+import { dirname } from 'node:path';
2894	+import remapping, { type SourceMapInput } from '@jridgewell/remapping';
2895	+import MagicString from 'magic-string';
2896	+import type { Plugin } from 'vite';
2897	+
2898	+// The map from positions in `html` to the sources of `code`, the script
2899	+// vite-plugin-singlefile inlined into it with `codeMap` as its map. Makes the
2900	+// plugin's edits to the script again (its replaceScript) and fails unless
2901	+// they give back the script exactly as `html` holds it.
2902	+export function mapInlinedScript(html: string, code: string, codeMap: SourceMapInput, codeFile: string): string {
2903	+  const edited = new MagicString(code);
2904	+  for (const found of code.matchAll(/"?__VITE_PRELOAD__"?/g)) {
2905	+    edited.overwrite(found.index, found.index + found[0].length, 'void 0');
2906	+  }
2907	+  for (const found of code.matchAll(/<(\/script>|!--)/g)) {
2908	+    edited.overwrite(found.index, found.index + 1, '\\x3C');
2909	+  }
2910	+  edited.trim();
2911	+  const inlined = edited.toString();
2912	+  const at = html.indexOf(inlined);
2913	+  if (at < 0 || html.indexOf(inlined, at + 1) >= 0) {
2914	+    throw new Error(`index.html does not hold ${codeFile} exactly once as vite-plugin-singlefile inlines it, so no source map can be made`);
2915	+  }
2916	+  edited.prepend(html.slice(0, at));
2917	+  edited.append(html.slice(at + inlined.length));
2918	+  const htmlMap = edited.generateMap({ source: codeFile, file: 'index.html', hires: 'boundary' });
2919	+  const map = remapping(htmlMap.toString(), (source) => (source === codeFile ? codeMap : null));
2920	+  map.file = 'index.html';
2921	+  return map.toString();
2922	+}
2923	+
2924	+// Vite plugins: the first keeps the built script and its map before
2925	+// vite-plugin-singlefile inlines it, the second writes the map of the
2926	+// finished index.html to `mapFile`. List them after viteSingleFile().
2927	+export function inlinedScriptSourceMap(mapFile: string): Plugin[] {
2928	+  const scripts = new Map<string, { code: string; map: SourceMapInput }>();
2929	+  return [
2930	+    {
2931	+      name: 'jusprin:keep-script-map',
2932	+      apply: 'build',
2933	+      config: () => ({ build: { sourcemap: 'hidden' } }),
2934	+      generateBundle: {
2935	+        order: 'pre',
2936	+        handler(_options, bundle) {
2937	+          for (const output of Object.values(bundle)) {
2938	+            if (output.type !== 'chunk' || output.map == null) continue;
2939	+            scripts.set(output.fileName, { code: output.code, map: output.map as SourceMapInput });
2940	+            // The script's own map would ship with the page.
2941	+            delete bundle[`${output.fileName}.map`];
2942	+          }
2943	+        },
2944	+      },
2945	+    },
2946	+    {
2947	+      name: 'jusprin:inlined-script-map',
2948	+      apply: 'build',
2949	+      enforce: 'post',
2950	+      generateBundle(_options, bundle) {
2951	+        const page = bundle['index.html'];
2952	+        if (page?.type !== 'asset' || scripts.size !== 1) {
