3430	+// Calls itself `depth` times, then throws; the work after each call keeps
3431	+// every call a frame of its own.
3432	+JUSPRIN_NOINLINE void throw_deep(int depth)
3433	+{
3434	+    if (depth == 0)
3435	+        throw std::runtime_error("thrown deep");
3436	+    throw_deep(depth - 1);
3437	+    g_after_call = g_after_call + 1;
3438	+}
3439	+
3440	+// Whether `frame` is a return address inside `function`, whose code is far
3441	+// shorter than 1 KiB.
3442	+template<class Function> bool inside(Function* function, void* frame)
3443	+{
3444	+    const auto start   = reinterpret_cast<std::uintptr_t>(function);
3445	+    const auto address = reinterpret_cast<std::uintptr_t>(frame);
3446	+    return address >= start && address < start + 1024;
3447	+}
3448	+
3449	+bool in_throw_deep(void* frame) { return inside(&throw_deep, frame); }
3450	+
3451	+// Finds a failure that is no exception, as code holding an HTTP status does.
3452	+JUSPRIN_NOINLINE std::vector<void*> find_failure_as_value()
3453	+{
3454	+    std::vector<void*> stack = failure_stack();
3455	+    g_after_call = g_after_call + 1;
3456	+    return stack;
3457	+}
